// Leading line comment
/* Block comment
   spanning lines */
/** Doc-ish comment */
#include <stdio.h>
#include <stdlib.h>
#include "local/header.h"
#include MACRO_HEADER
#define GREETING "hello"
#pragma once

typedef int myint;
typedef unsigned long ulong_t;
typedef struct Point { int x; int y; } Point;
typedef enum Color { RED, GREEN = 3, BLUE } Color;
typedef union Value { int i; float f; } Value;
typedef void (*Callback)(int a, char *b);

struct Bare {
    int field_a;
    char *name;
};

enum Standalone { ONE, TWO };

union Raw {
    int i;
    double d;
};

static int global_counter = 0;
const char *global_name = "world";
int arr[3] = {1, 2, 3};
int a1, a2 = 5;

int declared_func(int x, char *y);
void voidfn(void);
extern int extern_var;

int add(int a, int b) {
    int local = a + b;
    return local;
}

static void process(struct Point *p, char sep) {
    char buf[64];
    int i = 0;
    printf("value=%d\n", p->x);
    sprintf(buf, "%c", sep);

    if (p->x > 0) {
        puts("positive");
    } else if (p->x == 0) {
        puts("zero");
    } else {
        puts("negative");
    }

    for (i = 0; i < 10; i++) {
        printf("%d", i);
    }

    while (i > 0) {
        i--;
    }

    do {
        i++;
    } while (i < 5);

    switch (p->y) {
        case 1:
            puts("one");
            break;
        default:
            break;
    }
}

int main(int argc, char **argv) {
    struct Point pt = {1, 2};
    process(&pt, ',');
    add(1, 2);
    return add(3, 4);
}
CEOF
